from music21 import stream, note, chord, meter, tempo, key, instrument, dynamics, clef

score = stream.Score()
rh = stream.Part(); rh.insert(0, instrument.Piano()); rh.insert(0, clef.TrebleClef())
lh = stream.Part(); lh.insert(0, instrument.Piano()); lh.insert(0, clef.BassClef())
for p in (rh, lh):
    p.insert(0, meter.TimeSignature('4/4'))
    p.insert(0, key.Key('d'))
rh.insert(0, tempo.MetronomeMark(number=66))

# Ground bass: 8 half-notes over 4 bars
ground = ['D3','A2','B-2','F2','G2','D2','G2','A2']
# Harmony per half-bar (RH voicings)
harm = [['D4','F4','A4'],['C4','E4','A4'],['D4','F4','B-4'],['C4','F4','A4'],
        ['B-3','D4','G4'],['A3','D4','F4'],['B-3','D4','G4'],['C#4','E4','A4']]
# Melody: two quarters per half-bar
mel = [['A4','F5'],['E5','C5'],['D5','F5'],['C5','A4'],['B-4','D5'],['A4','F4'],['G4','B-4'],['A4','E4']]
# Counter-melody
cmel = [['D4','D4'],['C4','C4'],['B-3','D4'],['C4','C4'],['D4','B-3'],['D4','D4'],['D4','E4'],['E4','C#4']]

def up(p, oct_shift=1):
    n = note.Note(p); n.octave += oct_shift; return n.nameWithOctave

dyn_plan = ['pp','p','mp','mp','mf','f','mp','pp']

for cyc in range(8):
    rh.append(dynamics.Dynamic(dyn_plan[cyc]))
    lh.append(dynamics.Dynamic(dyn_plan[cyc]))
    for i in range(8):
        # Left hand
        if cyc == 5:
            b = ground[i]
            for q in range(2):
                n = note.Note(b); n.quarterLength = 1.0; lh.append(n)
        elif cyc in (2,3,4):
            n = note.Note(ground[i]); n.quarterLength = 1.0; lh.append(n)
            c = chord.Chord([ground[i], up(ground[i],1)]); c.quarterLength = 1.0; lh.append(c)
        else:
            n = note.Note(ground[i]); n.quarterLength = 2.0; lh.append(n)
        # Right hand
        if cyc == 0:
            r = note.Rest(); r.quarterLength = 2.0; rh.append(r)
        elif cyc == 1:
            c = chord.Chord(harm[i]); c.quarterLength = 2.0; rh.append(c)
        elif cyc == 2:
            pcs = harm[i]
            pattern = [pcs[0], pcs[1], pcs[2], up(pcs[0])]
            for p in pattern:
                n = note.Note(p); n.quarterLength = 0.5; rh.append(n)
        elif cyc == 3:
            for m in mel[i]:
                n = note.Note(m); n.quarterLength = 1.0; rh.append(n)
        elif cyc == 4:
            for q in range(2):
                c = chord.Chord([cmel[i][q], mel[i][q]]); c.quarterLength = 1.0; rh.append(c)
        elif cyc == 5:
            pcs = harm[i]
            pattern = [pcs[0], pcs[1], pcs[2], up(pcs[0]), up(pcs[1]), up(pcs[0]), pcs[2], pcs[1]]
            for p in pattern:
                n = note.Note(p); n.quarterLength = 0.25; rh.append(n)
            # melody also sounded above via separate voice simplified: skip
        elif cyc == 6:
            for q in range(2):
                n = note.Note(up(mel[i][q])); n.quarterLength = 1.0; rh.append(n)
        else:
            c = chord.Chord(harm[i]); c.quarterLength = 2.0; rh.append(c)

# Final cadence: D major chord (Picardy), 4 beats
rh.append(dynamics.Dynamic('ppp'))
fc = chord.Chord(['D4','F#4','A4','D5']); fc.quarterLength = 4.0; rh.append(fc)
fl = chord.Chord(['D2','A2']); fl.quarterLength = 4.0; lh.append(fl)

score.insert(0, rh)
score.insert(0, lh)
